{"file_path":"src/cli.js","content":"#!/usr/bin/env node
import { readFileSync } from 'node:fs'

class Fail extends Error {
  constructor(msg, code = 2) {
    super(msg)
    this.code = code
  }
}

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const tasks = new Map()
  const deps = []
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    if (w[0] === 'task') {
      if (w.length !== 3) throw new Fail(`error: line ${n}: expected task <name> <cost>`)
      if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) throw new Fail(`error: line ${n}: invalid task name ${w[1]}`)
      if (!/^[0-9]+$/.test(w[2])) throw new Fail(`error: line ${n}: cost must be a non-negative integer`)
      if (tasks.has(w[1])) throw new Fail(`error: line ${n}: task ${w[1]} is declared twice`)
      tasks.set(w[1], { name: w[1], cost: BigInt(w[2]), deps: new Set() })
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new Fail(`error: line ${n}: expected dep <name> <dependency>...`)
      deps.push(w.slice(1))
    } else {
      throw new Fail(`error: line ${n}: unknown directive ${w[0]}`)
    }
  })
  for (const d of deps) {
    for (const name of d) if (!tasks.has(name)) throw new Fail(`error: unknown task ${name}`)
    for (const x of d.slice(1)) tasks.get(d[0]).deps.add(x)
  }
  return tasks
}

function findCycle(tasks, names) {
  const state = new Map()
  const stack = []
  const visit = (name) => {
    state.set(name, 1)
    stack.push(name)
    for (const d of [...tasks.get(name).deps].sort(cmp)) {
      const s = state.get(d)
      if (s === 1) return [...stack.slice(stack.indexOf(d)), d]
      if (!s) {
        const c = visit(d)
        if (c) return c
      }
    }
    stack.pop()
    state.set(name, 2)
    return null
  }
  for (const name of names) if (!state.get(name)) {
    const c = visit(name)
    if (c) return c
  }
  return null
}

function main() {
  const args = process.argv.slice(2)
  const usage = 'error: usage: cli.js waves|explain|pack <workers>'
  const cmd = args[0]
  let workers = 0
  if ((cmd === 'waves' || cmd === 'explain') && args.length === 1) {
    // ok
  } else if (cmd === 'pack' && args.length === 2) {
    if (!/^[1-9][0-9]*$/.test(args[1])) throw new Fail('error: workers must be a positive integer')
    workers = Number(args[1])
  } else throw new Fail(usage)

  const tasks = parse(readFileSync(0, 'utf8'))
  const names = [...tasks.keys()].sort(cmp)
  const cycle = findCycle(tasks, names)
  if (cycle) throw new Fail(`error: cycle: ${cycle.join(' -> ')}`, 3)

  // topological order via memoised recursion (graph is acyclic)
  const start = new Map()
  const depth = new Map()
  const calc = (name) => {
    if (depth.has(name)) return
    let s = 0n
    let d = -1
    for (const x of tasks.get(name).deps) {
      calc(x)
      const f = start.get(x) + tasks.get(x).cost
      if (f > s) s = f
      if (depth.get(x) > d) d = depth.get(x)
    }
    start.set(name, s)
    depth.set(name, d + 1)
  }
  // iterative-safe enough: process in an order that limits recursion depth
  for (const n of names) calc(n)
  const finish = (n) => start.get(n) + tasks.get(n).cost
  let total = 0n
  for (const n of names) if (finish(n) > total) total = finish(n)

  let out = ''
  if (cmd === 'waves') {
    const waves = []
    for (const n of names) (waves[depth.get(n)] ||= []).push(n)
    waves.forEach((w, k) => (out += `wave ${k}: ${w.join(' ')}\n`))
    out += `total ${total}\n`
  } else if (cmd === 'explain') {
    for (const n of names) out += `${n} start=${start.get(n)} finish=${finish(n)} depth=${depth.get(n)}\n`
    out += `total ${total}\n`
  } else {
    const dependents = new Map(names.map((n) => [n, []]))
    for (const n of names) for (const d of tasks.get(n).deps) dependents.get(d).push(n)
    const prio = new Map()
    const pr = (n) => {
      if (prio.has(n)) return prio.get(n)
      let best = 0n
      for (const m of dependents.get(n)) {
        const p = pr(m)
        if (p > best) best = p
      }
      prio.set(n, best + tasks.get(n).cost)
      return prio.get(n)
    }
    for (const n of names) pr(n)
    const order = [...names].sort((a, b) => (prio.get(a) === prio.get(b) ? cmp(a, b) : prio.get(a) > prio.get(b) ? -1 : 1))
    const fin = new Map()
    const freeAt = Array(workers).fill(0n)
    const ran = Array.from({ length: workers }, () => [])
    let remaining = order.length
    let t = 0n
    let makespan = 0n
    while (remaining > 0) {
      for (;;) {
        const w = freeAt.findIndex((f) => f <= t)
        if (w < 0) break
        const pick = order.find(
          (n) => !fin.has(n) && [...tasks.get(n).deps].every((d) => fin.has(d) && fin.get(d) <= t),
        )
        if (!pick) break
        const f = t + tasks.get(pick).cost
        fin.set(pick, f)
        freeAt[w] = f
        ran[w].push(`${pick}@${t}-${f}`)
        if (f > makespan) makespan = f
        remaining--
      }
      if (remaining === 0) break
      let next = null
      for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
      for (const f of fin.values()) if (f > t && (next === null || f < next)) next = f
      if (next === null) break
      t = next
    }
    ran.forEach((r, i) => (out += `worker ${i}:${r.map((x) => ' ' + x).join('')}\n`))
    out += `makespan ${makespan}\n`
  }
  process.stdout.write(out)
}

try {
  main()
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exit(e.code)
}
"}

